-- TAN_SUAT: 1=Tháng, 2=Quý, 3=Năm
-- Đây là danh sách mẫu gợi ý — admin có thể thêm/sửa qua UI sau khi hệ thống lên production.

-- KyCode tự sinh = {NAM}Q{Q}_{MA_MAU} | {NAM}T{MM}_{MA_MAU} | {NAM}_{MA_MAU}
-- Không cần KY_CODE_PREFIX riêng vì MA_MAU đã là prefix ngắn gọn, unique.

MERGE INTO RPT_MAU_BAO_CAO d USING (SELECT 8001 ID FROM dual) s ON (d.ID = s.ID)
