MERGE INTO CODES d USING (SELECT 'CAP_BAC_CONG_AN' CODE FROM dual) s ON (d.CODE = s.CODE)
WHEN MATCHED THEN UPDATE SET d.NAME = 'Cấp bậc công an', d.IS_ACTIVE = 1, d.IS_SYSTEM = 1, d.UPDATED_AT = SYSTIMESTAMP
WHEN NOT MATCHED THEN INSERT (CODE, NAME, IS_ACTIVE, IS_SYSTEM, CREATED_AT, UPDATED_AT)
VALUES ('CAP_BAC_CONG_AN', 'Cấp bậc công an', 1, 1, SYSTIMESTAMP, SYSTIMESTAMP);

MERGE INTO CODE_VALUES d USING (SELECT c.ID CODE_ID, 'THIEU_UY' VALUE, 'Thiếu úy' NAME, 1 SORT_ORDER FROM CODES c WHERE c.CODE = 'CAP_BAC_CONG_AN') s ON (d.CODE_ID = s.CODE_ID AND d.VALUE = s.VALUE)
WHEN MATCHED THEN UPDATE SET d.NAME = s.NAME, d.SORT_ORDER = s.SORT_ORDER, d.IS_ACTIVE = 1, d.IS_SYSTEM = 1, d.UPDATED_AT = SYSTIMESTAMP
WHEN NOT MATCHED THEN INSERT (CODE_ID, VALUE, NAME, SORT_ORDER, IS_ACTIVE, IS_SYSTEM, CREATED_AT, UPDATED_AT)
VALUES (s.CODE_ID, s.VALUE, s.NAME, s.SORT_ORDER, 1, 1, SYSTIMESTAMP, SYSTIMESTAMP);

